import React, { useState } from "react";
import {
  Box,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  List,
  ListItem,
  ListItemText,
} from "@mui/material";
import { useParams, useNavigate } from "react-router-dom";

// Mock data for election results
const mockElectionResults = [
  {
    id: 1,
    name: "SRC Election 2023",
    startDate: "2023-10-01",
    startTime: "08:00",
    endDate: "2023-10-02",
    endTime: "20:00",
    positions: [
      {
        title: "President",
        candidates: [
          { name: "Candidate 1a", votes: 150 },
          { name: "Candidate 1b", votes: 120 },
          { name: "Candidate 1c", votes: 80 },
        ],
      },
      {
        title: "Vice President",
        candidates: [
          { name: "Candidate 2a", votes: 130 },
          { name: "Candidate 2b", votes: 110 },
          { name: "Candidate 2c", votes: 90 },
        ],
      },
    ],
  },
  {
    id: 2,
    name: "SRC Election 2024",
    startDate: "2024-10-01",
    startTime: "08:00",
    endDate: "2024-10-02",
    endTime: "20:00",
    positions: [
      {
        title: "President",
        candidates: [
          { name: "Candidate 1a", votes: 200 },
          { name: "Candidate 1b", votes: 180 },
          { name: "Candidate 1c", votes: 150 },
        ],
      },
      {
        title: "Vice President",
        candidates: [
          { name: "Candidate 2a", votes: 190 },
          { name: "Candidate 2b", votes: 170 },
          { name: "Candidate 2c", votes: 140 },
        ],
      },
    ],
  },
];

const ViewResults = () => {
  const { electionId } = useParams();
  const navigate = useNavigate();
  const [openDialog, setOpenDialog] = useState(!electionId); // Open dialog if no electionId is provided

  const election = mockElectionResults.find((election) => election.id === parseInt(electionId));

  const handleOpenDialog = () => {
    setOpenDialog(true);
  };

  const handleCloseDialog = () => {
    setOpenDialog(false);
  };

  const handleSelectElection = (id) => {
    navigate(`/admin/results/${id}`);
    handleCloseDialog();
  };

  if (!electionId) {
    return (
      <Box sx={{ p: 4, minHeight: "100vh" }}>
        <Typography variant="h4" fontWeight="bold" align="center" mb={4}>
          View Election Results
        </Typography>
        <Box sx={{ textAlign: "center" }}>
          <Button
            variant="contained"
            onClick={handleOpenDialog}
            sx={{
              bgcolor: "#007bff",
              color: "white",
              "&:hover": { bgcolor: "#0056b3" },
            }}
          >
            Select Election to View
          </Button>
        </Box>

        {/* Dialog for selecting an election */}
        <Dialog open={openDialog} onClose={handleCloseDialog} fullWidth maxWidth="sm">
          <DialogTitle sx={{ backgroundColor: "#007bff", color: "white" }}>
            Select Election
          </DialogTitle>
          <DialogContent>
            <List>
              {mockElectionResults.map((election) => (
                <ListItem
                  button
                  key={election.id}
                  onClick={() => handleSelectElection(election.id)}
                >
                  <ListItemText primary={election.name} secondary={`${election.startDate} to ${election.endDate}`} />
                </ListItem>
              ))}
            </List>
          </DialogContent>
          <DialogActions>
            <Button
              onClick={handleCloseDialog}
              sx={{ color: "#6c757d", "&:hover": { color: "#5a6268" } }}
            >
              Close
            </Button>
          </DialogActions>
        </Dialog>
      </Box>
    );
  }

  if (!election) {
    return (
      <Box sx={{ p: 4, textAlign: "center" }}>
        <Typography variant="h4" fontWeight="bold" mb={4}>
          Election Not Found
        </Typography>
      </Box>
    );
  }

  return (
    <Box sx={{ p: 4, minHeight: "100vh" }}>
      {/* Election Details */}
      <Typography variant="h4" fontWeight="bold" align="center" mb={4}>
        {election.name}
      </Typography>
      <Typography variant="h6" align="center" mb={2}>
        Start: {election.startDate} {election.startTime}
      </Typography>
      <Typography variant="h6" align="center" mb={4}>
        End: {election.endDate} {election.endTime}
      </Typography>

      {/* Positions and Candidates */}
      {election.positions.map((position, index) => (
        <Box key={index} sx={{ mb: 4 }}>
          <Typography variant="h5" fontWeight="bold" mb={2}>
            {position.title}
          </Typography>
          <TableContainer component={Paper} sx={{ borderRadius: "16px", boxShadow: 4 }}>
            <Table>
              <TableHead>
                <TableRow sx={{ backgroundColor: "#007bff" }}>
                  <TableCell sx={{ color: "white", fontWeight: "bold" }}>Candidate</TableCell>
                  <TableCell sx={{ color: "white", fontWeight: "bold" }}>Votes</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {position.candidates.map((candidate, idx) => (
                  <TableRow key={idx} sx={{ "&:hover": { backgroundColor: "rgba(0, 123, 255, 0.1)" } }}>
                    <TableCell>{candidate.name}</TableCell>
                    <TableCell>{candidate.votes}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </Box>
      ))}
    </Box>
  );
};

export default ViewResults;
